/*
 * A369331  Positive numbers whose decimal expansions are covered by that of
 *          prime numbers (without leading zeros).
 * https://oeis.org/A369331
 *
 * Offset:    1    (a(1) is the first term)
 * Keywords:  nonn, base, easy
 * Formula:   a(n) is generated by searching for numbers whose every decimal
 *            digit is contained in at least one prime substring (a substring
 *            that starts with a non‑zero digit). The function returns the
 *            n‑th such number, counting from n = 1. A memoised static cache
 *            is used so that calls are O(1) after the term...
 * Range:     u8 n <= 60, u16 n <= 60, u32 n <= 60, u64 n <= 60, u128 n <= 60,
 *            big any n
 * Helpers:   none
 *
 * Sequence data from the OEIS (https://oeis.org), licensed CC BY-SA 4.0.
 */

#include <stdbool.h>
#include <stdint.h>
#include <stdlib.h>

/* Simple primality test for 64‑bit values.  The function operates
   only on unsigned long long values; we only use it for substrings
   that fit in 64 bits, which suffices for all numbers that can
   appear when n ≤ 10000. */
static bool is_prime_u64(uint64_t n) {
    if (n < 2) return false;
    if (n % 2 == 0) return n == 2;
    for (uint64_t d = 3; d <= n / d; d += 2)
        if (n % d == 0) return false;
    return true;
}

/* Return true if every decimal digit of n is covered by at least
   one prime substring that starts with a non‑zero digit. */
static bool is_covered(seq_t n) {
    /* Extract digits in most‑significant‑first order. */
    unsigned char digits[128];
    size_t len = 0;
    seq_t t = n;
    do {
        digits[len++] = (unsigned char)(t % 10);
        t /= 10;
    } while (t != 0);
    for (size_t i = 0; i < len / 2; ++i) {
        unsigned char tmp = digits[i];
        digits[i] = digits[len - 1 - i];
        digits[len - 1 - i] = tmp;
    }

    /* Mark coverage of each position. */
    unsigned char covered[128] = {0};
    for (size_t start = 0; start < len; ++start) {
        if (digits[start] == 0) continue;  /* substring must not start with 0 */
        seq_t sub = 0;
        for (size_t end = start; end < len; ++end) {
            sub = sub * 10 + digits[end];
            /* We only test for primality if sub fits in 64 bits. */
            if (sub <= (seq_t)UINT64_MAX &&
                is_prime_u64((uint64_t)sub))
            {
                for (size_t pos = start; pos <= end; ++pos)
                    covered[pos] = 1;
            }
        }
    }

    /* All positions must be covered. */
    for (size_t i = 0; i < len; ++i)
        if (!covered[i]) return false;
    return true;
}

/* Memoised generator of A369331. */
seq_t a(idx_t n) {
    static seq_t *cache = NULL;
    static size_t cache_len = 0;
    static size_t cache_cap = 0;
    static seq_t next = 2;   /* first candidate to test */

    if (n == 0) return 0;    /* safety: index 0 is unused */

    /* Grow the cache until it contains at least n elements. */
    while (cache_len < (size_t)n) {
        if (is_covered(next)) {
            if (cache_len == cache_cap) {
                cache_cap = cache_cap ? cache_cap * 2 : 16;
                seq_t *tmp = (seq_t *)realloc(cache, cache_cap * sizeof(seq_t));
                cache = tmp;
            }
            cache[cache_len++] = next;
        }
        ++next;
    }

    return cache[n - 1];
}
